svg.script:
(function() {
  function getQueryParams() {
    var params = {};
    var search = window.location.search.substring(1);
    if (search) {
      var pairs = search.split("&");
      for (var i = 0; i < pairs.length; i++) {
        var pair = pairs[i].split("=");
        params[decodeURIComponent(pair[0]).toLowerCase()] = decodeURIComponent(pair[1] || '');
      }
    }
    return params;
  }

  var params = getQueryParams();

  // Update text name
  if (params.name) {
    var labelEl = document.getElementById('box-label');
    if (labelEl) {
      labelEl.textContent = params.name;
    }
  }

  // Update background colour
  if (params.colour || params.color) {
    var bgEl = document.getElementById('square-bg');
    if (bgEl) {
      bgEl.style.fill = params.colour || params.color;
    }
  }
})();
